const leaveEmployeeName = (row) => { const employee=row?.employeeId||row?.employee; return employee&&typeof employee==="object"?[employee.firstName,employee.lastName].filter(Boolean).join(" ")||employee.employeeCode||"—":row?.employeeName||"—"; };
const leaveColumns = [{ key: "employeeId", label: "Employee", render: (_value,row) => leaveEmployeeName(row) }, { key: "startDate", label: "From", render: DateText }, { key: "endDate", label: "To", render: DateText }, { key: "reason", label: "Reason" }, { key: "status", label: "Status", render: StatusBadge }];
export function MyLeaveWorkspace() {
  const [types,setTypes]=useState([]); const [cancel,setCancel]=useState(); const [reason,setReason]=useState(""); const [busy,setBusy]=useState(false); const [error,setError]=useState(""); const [showCalendar,setShowCalendar]=useState(false);
  useEffect(()=>{let active=true;leave.handleGetLeaveTypes().then(data=>{if(active)setTypes(unwrapCollection(data).items);}).catch(e=>{if(active)setError(e.message);});return()=>{active=false;};},[]);
  const cancelRequest=async(reload)=>{setBusy(true);setError("");try{transitionResult(await leave.handleCancelLeave(cancel._id,{reason}));setCancel();setReason("");await reload();}catch(e){setError(e.message);}finally{setBusy(false);}};
  return <>{error&&<div className="page-content page-content--notice"><ErrorState message={error}/></div>}{showCalendar?<main className="page-content"><PageHeading meta="My leave history" title="My leave calendar" description="Review your leave requests and their status by month." actions={<Button variant="secondary" icon={List} onClick={()=>setShowCalendar(false)}>Back to leave list</Button>}/><LeaveCalendar ownOnly/></main>:<ResourceWorkspace api={leave} title="My leave" meta="Time away" description="Request leave and follow each decision from the approval queue." read={["handleGetMyLeave"]} create={["handleSubmitLeave"]} createLabel="Request leave" secondary={<Button variant="secondary" icon={CalendarDays} onClick={()=>setShowCalendar(true)}>Leave calendar</Button>} columns={leaveColumns} fields={[{ name: "leaveTypeId", label: "Leave type", type:"select", options:types.map(type=>({value:type._id,label:type.name})), required: true }, { name: "startDate", label: "Start date", type: "date", required: true }, { name: "endDate", label: "End date", type: "date", required: true }, { name: "reason", label: "Reason", type: "textarea", span: 2 }]} rowActions={(row,{reload})=>row.status==="PENDING"?<Button variant="danger" onClick={()=>setCancel({...row,reload})}>Cancel request</Button>:null} emptyDescription="Your leave requests will appear here." />}
    <Modal open={Boolean(cancel)} onClose={()=>setCancel()} title="Cancel leave request" description="The request will remain in your history with a cancelled status." footer={<><Button variant="secondary" onClick={()=>setCancel()}>Keep request</Button><Button variant="danger" loading={busy} disabled={!reason.trim()} onClick={()=>cancelRequest(cancel.reload)}>Cancel leave</Button></>}><Field label="Reason" helper="Required for a clear approval trail"><textarea value={reason} required onChange={e=>setReason(e.target.value)}/></Field></Modal></>;
}
const LEAVE_QUEUE_FILTER_KEYS = ["status", "employeeId", "from", "to"];

export function LeaveQueueWorkspace() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [rows, setRows] = useState([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [decision,setDecision]=useState(); const [note,setNote]=useState(""); const [busy,setBusy]=useState(false); const [showCalendar,setShowCalendar]=useState(false);
  const filterKey = JSON.stringify(Object.fromEntries(LEAVE_QUEUE_FILTER_KEYS.map((key) => [key, searchParams.get(key) || ""]).filter(([, value]) => value)));
  const clearFilter = (key) => setSearchParams((current) => { const next = new URLSearchParams(current); next.delete(key); return next; }, { replace: true });
  const load = useCallback(async () => { setLoading(true); try { setRows(unwrapCollection(await leave.handleGetLeaveQueue({ status: "PENDING", ...JSON.parse(filterKey), page: 1, limit: 50 })).items); setError(""); } catch (e) { setError(e.message); } finally { setLoading(false); } }, [filterKey]);
  useEffect(() => { load(); }, [load]);
  const act = async () => { setBusy(true);try { transitionResult(await (decision.approve ? leave.handleApproveLeave(decision.row._id, note ? { note } : {}) : leave.handleRejectLeave(decision.row._id, { note })));setDecision();setNote("");await load(); } catch (e) { setError(e.message); } finally{setBusy(false);} };
  return <main className="page-content"><PageHeading meta={showCalendar?"Leave history":"Approvals"} title={showCalendar?"Leave calendar":"Leave queue"} description={showCalendar?"A monthly view of employee leave requests and their decision history.":"Pending requests requiring an explicit decision."} actions={<Button variant={showCalendar?"secondary":"primary"} icon={showCalendar?List:CalendarDays} onClick={()=>setShowCalendar(current=>!current)}>{showCalendar?"Back to queue":"Leave calendar"}</Button>}/>{showCalendar?<LeaveCalendar/>:<section className="surface">{Object.keys(JSON.parse(filterKey)).length ? <div className="toolbar">{Object.entries(JSON.parse(filterKey)).map(([key, value]) => <button type="button" className="crm-monitor-chip" key={key} onClick={() => clearFilter(key)} aria-label={`Remove the ${key} filter`}><small>{key}</small><b>{String(value).replaceAll("_", " ")}</b><X size={12} aria-hidden="true" /></button>)}</div> : null}{loading ? <Skeleton rows={6}/> : error ? <ErrorState message={error} onRetry={load}/> : rows.length ? <DataTable rows={rows} columns={leaveColumns} actions={(row)=><div className="inline-actions"><Button variant="quiet" icon={ThumbsUp} onClick={()=>setDecision({row,approve:true})}>Approve</Button><Button variant="danger" icon={ThumbsDown} onClick={()=>setDecision({row,approve:false})}>Reject</Button></div>}/> : <EmptyState title="The queue is clear" description="There are no pending leave requests."/>}</section>}<Modal open={Boolean(decision)} onClose={()=>setDecision()} title={decision?.approve?"Approve leave request":"Reject leave request"} description={`${leaveEmployeeName(decision?.row)} · ${decision?.row?.startDate||""} to ${decision?.row?.endDate||""}`} footer={<><Button variant="secondary" onClick={()=>setDecision()}>Cancel</Button><Button variant={decision?.approve?"primary":"danger"} loading={busy} disabled={!decision?.approve&&!note.trim()} onClick={act}>{decision?.approve?"Approve request":"Reject request"}</Button></>}><Field label={decision?.approve?"Decision note (optional)":"Reason for rejection"}><textarea value={note} required={!decision?.approve} onChange={e=>setNote(e.target.value)}/></Field></Modal></main>;
}

