  const [record,setRecord]=useState(); const [form,setForm]=useState({}); const [editing,setEditing]=useState(false); const [loading,setLoading]=useState(true); const [saving,setSaving]=useState(false); const [error,setError]=useState("");
  const load=useCallback(async()=>{if(!isValid)return;setLoading(true);try{setRecord(await vendors.handleGetVendor(id));setError("");}catch(e){setError(e.message);}finally{setLoading(false);}},[id,isValid]);
  useEffect(()=>{load();},[load]);
